-- OK: 119 researched stops.
--
-- 0 new, 119 updating a row already in the index.
-- After running this and scripts/refresh-site.mts, /explore should read
-- 6298.
--
-- Coordinates are deliberately NOT updated on conflict: a checked position
-- must never be replaced by an unchecked one. Where the existing row came
-- from the OpenStreetMap scan and is wrong by a kilometre, delete that slug
-- first and let this insert instead.
--
-- state is deliberately NOT updated either. That is how an overwritten stop
-- in another state keeps its old state and hides — so the collision check
-- above refuses rather than relying on anyone noticing afterwards.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, timezone)
values
  ('Blue Whale of Catoosa', 'blue-whale-of-catoosa', 'roadside-oddities', 36.19352, -95.7331, 'Catoosa', 'OK', 'Built by Hugh Davis in the early 1970s, this huge smiling concrete whale rises from a pond beside historic Route 66. The former swimming-hole attraction has become one of Oklahoma''s defining pieces of roadside Americana.', 'open', 'https://www.travelok.com/listings/view.profile/id.867', 'America/Chicago'),
  ('Ed Galloway''s Totem Pole Park', 'ed-galloways-totem-pole-park', 'roadside-oddities', 36.43722, -95.44806, 'Foyil', 'OK', 'Self-taught artist Ed Galloway covered a rural property with concrete folk-art structures, including a towering hand-built totem pole and an elaborate concrete fiddle house. The site is one of the state''s strongest genuine outsider-art stops.', 'open', 'https://www.travelok.com/listings/view.profile/id.7706', 'America/Chicago'),
  ('Buck Atom''s Cosmic Curios on 66', 'buck-atoms-cosmic-curios-on-66', 'roadside-oddities', 36.14806, -95.97365, 'Tulsa', 'OK', 'A 21-foot Muffler Man transformed into a space cowboy stands outside this Route 66 shop, mixing Tulsa''s western imagery with atomic-age kitsch. Buck Atom has become a modern Mother Road landmark rather than a surviving vintage advertisement.', 'open', 'https://buckatomson66.com/', 'America/Chicago'),
  ('Meadow Gold Sign', 'meadow-gold-sign', 'roadside-oddities', 36.14776, -95.97468, 'Tulsa', 'OK', 'The restored Meadow Gold neon sign once advertised dairy products from a different location along Route 66. Tulsa preserved and relocated the huge rooftop sign to a dedicated plaza, where it again lights the Mother Road corridor.', 'roadside', 'https://www.cityoftulsa.org/route-66/route-66-attractions/', 'America/Chicago'),
  ('Golden Driller', 'golden-driller', 'roadside-oddities', 36.13364, -95.93116, 'Tulsa', 'OK', 'The 75-foot Golden Driller towers outside Expo Square as an oversized tribute to Oklahoma''s petroleum industry. The concrete-and-plaster figure is one of the tallest free-standing statues in the United States.', 'open', 'https://www.travelok.com/listings/view.profile/id.2137', 'America/Chicago'),
  ('Cyrus Avery Centennial Plaza', 'cyrus-avery-centennial-plaza', 'roadside-oddities', 36.1446, -96.00335, 'Tulsa', 'OK', 'This riverfront plaza honors Tulsa businessman Cyrus Avery, a central figure in the creation and promotion of U.S. Route 66. Sculptures, plaques and views toward the historic bridge turn the highway''s origin story into a physical stop.', 'open', 'https://www.cityoftulsa.org/route-66/route-66-attractions/', 'America/Chicago'),
  ('East Meets West: Symbolic Route 66 Midpoint', 'east-meets-west-symbolic-route-66-midpoint', 'roadside-oddities', 36.14458, -96.0032, 'Tulsa', 'OK', 'The bronze East Meets West sculpture depicts a Model T encountering a horse-drawn carriage at the Arkansas River crossing, symbolizing the transition from old transportation to the automobile age. It sits within the Cyrus Avery plaza but is a distinct large-scale artwork.', 'open', 'https://www.hmdb.org/m.asp?m=172088', 'America/Chicago'),
  ('Route 66 Rising', 'route-66-rising', 'roadside-oddities', 36.16071, -95.86884, 'Tulsa', 'OK', 'A huge stylized Route 66 shield rises beside the historic highway as a modern eastern gateway landmark. Its scale makes it function more like public sculpture than an ordinary road sign.', 'roadside', 'https://www.cityoftulsa.org/route-66/route-66-attractions/', 'America/Chicago'),
  ('Route 66 Historical Village', 'route-66-historical-village', 'weird-history', 36.10835, -96.01588, 'Tulsa', 'OK', 'This outdoor village gathers a restored oil derrick, locomotive, railcars and other artifacts tied to Tulsa''s oil and transportation history. The collection turns an old industrial corridor into a compact open-air Route 66 museum.', 'open', 'https://www.route66village.com/', 'America/Chicago'),
  ('Tulsa Cave House', 'tulsa-cave-house', 'roadside-oddities', 36.1571, -96.01295, 'Tulsa', 'OK', 'Built in the 1920s as the Cave Garden Restaurant, this deliberately grotto-like house is tied to stories of Prohibition-era drinking and a now-sealed tunnel beneath the hill. Interior tours are by appointment only.', 'limited', 'https://www.travelok.com/listings/view.profile/id.22342', 'America/Chicago'),
  ('World''s Largest Praying Hands', 'worlds-largest-praying-hands', 'roadside-oddities', 36.05206, -95.95698, 'Tulsa', 'OK', 'Two enormous bronze hands rise from the entrance area of Oral Roberts University in a monumental gesture of prayer. The sculpture''s scale makes it one of Tulsa''s strangest pieces of religious public art.', 'open', 'https://www.travelok.com/listings/view.profile/id.22675', 'America/Chicago'),
  ('Quan Am Bodhisattva Statue', 'quan-am-bodhisattva-statue', 'roadside-oddities', 36.134, -95.7905, 'Tulsa', 'OK', 'A monumental statue of Quan Am stands on the grounds of the Tam Bao Buddhist Temple in east Tulsa. Visitors should treat the temple as an active religious site and follow posted access expectations.', 'limited', 'https://www.travelok.com/listings/view.profile/id.22633', 'America/Chicago'),
  ('Meadow Gold Mack — Friendly Lumberjack', 'meadow-gold-mack-friendly-lumberjack', 'roadside-oddities', 36.14765, -95.97357, 'Tulsa', 'OK', 'This restored-style Muffler Man stands near the Meadow Gold sign in Tulsa''s growing cluster of Route 66 giants. His classic lumberjack form adds another piece of fiberglass roadside culture to the corridor.', 'roadside', 'https://www.waymarking.com/waymarks/wm1C64Q_Meadow_Gold_Mack_The_Friendly_Lumberjack_Tulsa_OK', 'America/Chicago'),
  ('Cowboy Bob Muffler Man', 'cowboy-bob-muffler-man', 'roadside-oddities', 36.1481, -95.97325, 'Tulsa', 'OK', 'Installed in 2025, Cowboy Bob is a 21-foot guitar-playing Muffler Man designed as a honky-tonk cowboy. He stands across Route 66 from Tulsa''s other modern giants, making the block an unusually dense roadside-statue cluster.', 'roadside', 'https://www.travelok.com/listings/view.profile/id.36699', 'America/Chicago'),
  ('Stay Gold Neon Sign at Circle Cinema', 'stay-gold-neon-sign-at-circle-cinema', 'roadside-oddities', 36.15944, -95.95845, 'Tulsa', 'OK', 'A glowing Stay Gold sign beside the historic Circle Cinema references S.E. Hinton''s The Outsiders and Tulsa''s connection to the film adaptation. The theater itself appeared in the movie, giving the neon a direct local pop-culture tie.', 'roadside', 'https://www.route66news.com/2022/10/19/companion-neon-sign-erected-next-to-circle-cinema-in-tulsa/', 'America/Chicago'),
  ('Gold Dome', 'gold-dome', 'roadside-oddities', 35.4928, -97.53083, 'Oklahoma City', 'OK', 'This 1958 geodesic bank building is wrapped in a gold-colored dome at a prominent Route 66-era intersection. Its futuristic geometry remains one of Oklahoma City''s most recognizable mid-century landmarks.', 'roadside', 'https://www.travelok.com/articles/roadside-oddities-along-route-66', 'America/Chicago'),
  ('Milk Bottle Grocery', 'milk-bottle-grocery', 'roadside-oddities', 35.4942, -97.5319, 'Oklahoma City', 'OK', 'A huge metal milk bottle sits on the roof of a tiny triangular commercial building along old Route 66. Added around 1948, the bottle turned an otherwise modest grocery into a classic roadside attention-grabber.', 'roadside', 'https://www.travelok.com/articles/roadside-oddities-along-route-66', 'America/Chicago'),
  ('Giant Sonic Drink Water Tank', 'giant-sonic-drink-water-tank', 'roadside-oddities', 35.39017, -97.2644, 'Oklahoma City', 'OK', 'A water tank beside the Sonic at I-40 and Choctaw Road is painted and shaped to resemble an enormous Sonic soft drink. It is a modern piece of branded roadside absurdity visible from the highway corridor.', 'roadside', 'https://www.waymarking.com/waymarks/wm10B5K_Sonic_at_I_40_and_Choctaw_Rd_Choctaw_OK', 'America/Chicago'),
  ('Blue Hippo', 'blue-hippo', 'roadside-oddities', 35.64163, -97.47835, 'Edmond', 'OK', 'The bright blue concrete hippo nicknamed Buddy has been moved around Edmond for decades and has become a local Route 66-era mascot. Its intentionally cheerful, oversized form makes it a strong quick photo stop.', 'roadside', 'https://www.travelok.com/listings/view.profile/id.26791', 'America/Chicago'),
  ('Arcadia Round Barn', 'arcadia-round-barn', 'roadside-oddities', 35.66233, -97.32623, 'Arcadia', 'OK', 'Built in 1898, this circular wooden barn survived long enough to become one of Oklahoma Route 66''s signature landmarks. Its unusual round construction and restored loft make it substantially stranger than an ordinary agricultural museum.', 'open', 'https://www.nps.gov/places/arcadia-round-barn.htm', 'America/Chicago'),
  ('POPS Giant Soda Bottle', 'pops-giant-soda-bottle', 'roadside-oddities', 35.65822, -97.33546, 'Arcadia', 'OK', 'A 66-foot illuminated soda bottle rises in front of POPS on Route 66. At night its programmable lights make the modern gas station and diner look like a deliberate revival of neon-era roadside spectacle.', 'open', 'https://pops66.com/', 'America/Chicago'),
  ('OK County 66 — John''s Place', 'ok-county-66-johns-place', 'roadside-oddities', 35.66237, -97.29262, 'Arcadia', 'OK', 'John Hargrove''s property is filled with homemade miniature versions of famous Route 66 landmarks, vintage pumps, signs and a tiny roadside theater. It functions like one person''s handmade shrine to the Mother Road.', 'open', 'https://www.travelok.com/listings/view.profile/id.22538', 'America/Chicago'),
  ('Paul McCartney Route 66 Sign', 'paul-mccartney-route-66-sign', 'roadside-oddities', 35.66372, -97.29878, 'Arcadia', 'OK', 'A roadside sign commemorates Paul McCartney''s low-key 2008 trip along Route 66 and his stop in Arcadia. The marker turns a brief celebrity road trip into a permanent piece of local highway lore.', 'roadside', 'https://www.travelok.com/listings/view.profile/id.30019', 'America/Chicago'),
  ('Lucille''s Service Station', 'lucilles-service-station', 'roadside-oddities', 35.53718, -98.58823, 'Hydro', 'OK', 'This tiny former gas station is closely associated with Lucille Hamons, the Route 66 operator remembered as the Mother of the Mother Road. The preserved building remains beside the old highway even though it no longer operates as a service station.', 'roadside', 'https://www.nps.gov/places/lucille-s-service-station.htm', 'America/Chicago'),
  ('Native American Muffler Man', 'native-american-muffler-man', 'roadside-oddities', 35.59207, -98.11869, 'Calumet', 'OK', 'A rare Native American-styled fiberglass giant stands beside the Indian Trading Post & Art on Route 66. The figure formerly stood at an auto dealership and was moved to this location in 2010.', 'open', 'https://web1.travelok.com/ie/listings/view.profile/id.22835', 'America/Chicago'),
  ('Route 66 Spaceman', 'route-66-spaceman', 'roadside-oddities', 35.5263, -98.70934, 'Weatherford', 'OK', 'A retro-futuristic spaceman figure stands along Route 66 in Weatherford, fitting the town''s connection to astronaut Thomas Stafford. The sculpture turns spaceflight imagery into a classic roadside photo stop.', 'roadside', 'https://www.travelok.com/Roadside_Oddities', 'America/Chicago'),
  ('The Sign on 66', 'the-sign-on-66', 'roadside-oddities', 35.52946, -98.84547, 'Weatherford', 'OK', 'Artist Corey Fuller''s installation combines sixteen hand-painted signs into one billboard-like collage made from reclaimed wood. It deliberately recreates the visual clutter and nostalgia of old highway advertising.', 'roadside', 'https://www.travelok.com/listings/view.profile/id.30912', 'America/Chicago'),
  ('Route 66 Car Wash Neon Sign', 'route-66-car-wash-neon-sign', 'roadside-oddities', 35.74954, -96.66911, 'Stroud', 'OK', 'A restored-style neon car-wash sign brightens the historic Route 66 corridor in Stroud. The oversized glowing advertisement was installed through Oklahoma''s Route 66 revitalization program.', 'roadside', 'https://www.travelok.com/listings/view.profile/id.37064', 'America/Chicago'),
  ('Route 66 Tool Tree', 'route-66-tool-tree', 'roadside-oddities', 35.74899, -96.66171, 'Stroud', 'OK', 'Old hand tools have been assembled into a tree-like metal sculpture outside a Route 66 hardware store. The object turns discarded work implements into a deliberately odd piece of roadside folk art.', 'roadside', 'https://www.travelok.com/listings/view.profile/id.29443', 'America/Chicago'),
  ('Chrysler-Plymouth Tower & Neon Sign', 'chrysler-plymouth-tower-neon-sign', 'roadside-oddities', 35.8328, -96.391, 'Bristow', 'OK', 'A 102-foot free-standing tower once advertised a 24-hour Chrysler-Plymouth dealership and has been restored as a Route 66 landmark. TravelOK identifies it as the tallest free-standing neon advertising sign on the historic highway.', 'roadside', 'https://www.travelok.com/listings/view.profile/id.37754', 'America/Chicago'),
  ('Waylan''s Ku-Ku Burger', 'waylans-ku-ku-burger', 'roadside-oddities', 36.8861, -94.8777, 'Miami', 'OK', 'A giant yellow cuckoo bird and surviving neon mark one of the last remnants of the Ku-Ku hamburger chain. The operating restaurant preserves a particularly strange piece of mid-century fast-food roadside design.', 'open', 'https://www.travelok.com/listings/view.profile/id.8426', 'America/Chicago'),
  ('Allen''s Conoco Fillin'' Station', 'allens-conoco-fillin-station', 'roadside-oddities', 36.933, -94.87747, 'Commerce', 'OK', 'This compact historic gas station survives along the Route 66 alignment through Commerce. Its restored pumps, signs and tiny building preserve the visual scale of early roadside service stations.', 'roadside', 'https://www.oklahomaroute66.com/', 'America/Chicago'),
  ('Mickey Mantle Memorial Statue', 'mickey-mantle-memorial-statue', 'roadside-oddities', 36.93329, -94.87246, 'Commerce', 'OK', 'A nine-foot bronze statue of baseball legend Mickey Mantle stands beside the high-school field in the town where he grew up. Commerce also renamed its Route 66 main street for Mantle, making the stop unusually tied to both sports and highway history.', 'open', 'https://www.travelok.com/listings/view.profile/id.26781', 'America/Chicago'),
  ('Catoosa Route 66 Monument', 'catoosa-route-66-monument', 'roadside-oddities', 36.18817, -95.74598, 'Catoosa', 'OK', 'Installed for the Route 66 centennial in 2026, this public monument incorporates locally chosen imagery including Catoosa''s Blue Whale. It is a new physical marker of the town''s long relationship with the Mother Road.', 'open', 'https://www.travelok.com/listings/view.profile/id.37736', 'America/Chicago'),
  ('F-4 Phantom Grove Display', 'f-4-phantom-grove-display', 'weird-history', 36.6307, -94.7663, 'Grove', 'OK', 'A retired F-4 Phantom II fighter is displayed beside the road in Grove as a memorial to people connected with the aircraft and military service. The full-size jet is an unexpectedly dramatic roadside object in northeastern Oklahoma.', 'roadside', 'https://www.travelok.com/listings/view.profile/id.27386', 'America/Chicago'),
  ('Winganon Space Capsule', 'winganon-space-capsule', 'roadside-oddities', 36.58278, -95.65164, 'Talala', 'OK', 'A cement mixer barrel left after a 1959 crash was later painted to resemble a NASA space capsule. The result looks like a tiny spacecraft that landed beside a rural Oklahoma highway.', 'roadside', 'https://www.travelok.com/Roadside_Oddities', 'America/Chicago'),
  ('Gasquatch', 'gasquatch', 'cryptids', 33.92386, -94.76851, 'Idabel', 'OK', 'A roughly thirty-foot Sasquatch figure towers over this combination gas station, restaurant and vintage-car display. The business leans fully into Bigfoot imagery, making it one of Oklahoma''s most literal cryptid roadside stops.', 'open', 'https://www.gasquatch.com/', 'America/Chicago'),
  ('Tin Woodsman', 'tin-woodsman', 'roadside-oddities', 36.74128, -102.51344, 'Boise City', 'OK', 'A 13-foot hand-built Tin Man stands outside the Cimarron Heritage Center Museum. Created to advertise a former cafe, the folk-art figure eventually returned to the Oklahoma Panhandle and now shares the grounds with a giant dinosaur.', 'open', 'https://www.travelok.com/listings/view.profile/id.22834', 'America/Chicago'),
  ('Cimmy the Dinosaur', 'cimmy-the-dinosaur', 'roadside-oddities', 36.74143, -102.51348, 'Boise City', 'OK', 'This 65-foot-long metal Apatosaurus looms outside the Cimarron Heritage Center. Cimmy was inspired by dinosaur remains recovered in Cimarron County and has become the Panhandle museum''s unmistakable roadside mascot.', 'open', 'https://www.travelok.com/listings/view.profile/id.22833', 'America/Chicago'),
  ('World''s Largest Peanut', 'worlds-largest-peanut', 'roadside-oddities', 33.99264, -96.37766, 'Durant', 'OK', 'A giant peanut monument stands on the lawn of Durant City Hall as a tribute to Bryan County peanut growers and processors. Its grand title is disputed by other giant peanuts, which only improves its OddWay value.', 'open', 'https://www.travelok.com/listings/view.profile/id.22732', 'America/Chicago'),
  ('Oklahoma''s Largest Cowboy Hat', 'oklahomas-largest-cowboy-hat', 'roadside-oddities', 36.12038, -97.89836, 'Hennessey', 'OK', 'This enormous cowboy hat was fabricated from recycled crude-oil tanks and weighs more than six tons. Mounted at a highway travel plaza, it turns western symbolism into literal roadside shelter and sculpture.', 'open', 'https://www.travelok.com/listings/view.profile/id.32440', 'America/Chicago'),
  ('Main Street Oil Well', 'main-street-oil-well', 'roadside-oddities', 36.5618, -96.16622, 'Barnsdall', 'OK', 'Barnsdall''s famous oil well sits directly in the middle of Main Street, forcing traffic to split around working-oil-country history. The well is a compact reminder of how completely petroleum development shaped parts of Oklahoma.', 'roadside', 'https://www.travelok.com/Roadside_Oddities', 'America/Chicago'),
  ('Roadside Revolver', 'roadside-revolver', 'roadside-oddities', 34.39832, -96.12042, 'Atoka', 'OK', 'A huge revolver sculpture points skyward beside the highway in Atoka. Its exaggerated scale turns a familiar Western object into a deliberately conspicuous roadside landmark.', 'roadside', 'https://www.travelok.com/Roadside_Oddities', 'America/Chicago'),
  ('Heffington Waterwheel', 'heffington-waterwheel', 'roadside-oddities', 34.23603, -96.67934, 'Tishomingo', 'OK', 'A large wooden waterwheel built in 2015 has become a downtown Tishomingo photo landmark. It has also appeared in country-music media, giving the otherwise decorative structure a small pop-culture afterlife.', 'roadside', 'https://tishomingo.com/visit-tishomingo/', 'America/Chicago'),
  ('East Maine Shark Bridge', 'east-maine-shark-bridge', 'roadside-oddities', 36.39578, -97.87518, 'Enid', 'OK', 'A low-clearance railroad bridge is painted with a giant shark mouth, transforming a notorious truck hazard into a visual joke. The mural makes the bridge''s warning impossible to miss even if the clearance sign is ignored.', 'roadside', 'https://visitenid.org/things-to-do/arts-culture/public-art/page/2/', 'America/Chicago'),
  ('Lazy Circles in the Sky', 'lazy-circles-in-the-sky', 'roadside-oddities', 36.39062, -97.8775, 'Enid', 'OK', 'Rust-colored steel hawks spiral upward at this gateway sculpture to downtown Enid. The title references Oklahoma! while the weathering steel echoes the color of red-tailed hawks seen over the plains.', 'open', 'https://visitenid.org/lazy-circles-in-the-sky/', 'America/Chicago'),
  ('Spider VW Bug', 'spider-vw-bug', 'roadside-oddities', 35.02847, -97.33598, 'Lexington', 'OK', 'A Volkswagen Beetle has been transformed into an enormous spider-like roadside sculpture. The familiar car body perched on long metal legs creates exactly the kind of inexplicable highway sight OddWay is built to surface.', 'roadside', 'https://www.travelok.com/Roadside_Oddities', 'America/Chicago'),
  ('Optimus Prime Statue', 'optimus-prime-statue', 'roadside-oddities', 36.1157, -97.03224, 'Stillwater', 'OK', 'A towering handmade interpretation of Optimus Prime stands beside a Stillwater business. The metal robot turns Transformers fandom into large-scale roadside sculpture.', 'roadside', 'https://www.travelok.com/Roadside_Oddities', 'America/Chicago'),
  ('Bumblebee Transformers Statue', 'bumblebee-transformers-statue', 'roadside-oddities', 36.11657, -97.12775, 'Stillwater', 'OK', 'A large yellow metal Bumblebee figure gives Stillwater a second oversized Transformers landmark. Its scrap-metal appearance makes the fictional robot read like industrial folk art from the road.', 'roadside', 'https://www.travelok.com/listings/view.profile/id.23048', 'America/Chicago'),
  ('Butterfly on a Giant Metal Hand', 'butterfly-on-a-giant-metal-hand', 'roadside-oddities', 34.78638, -96.95912, 'Stratford', 'OK', 'A huge fabricated metal hand delicately holds a butterfly outside a welding business south of Stratford. There is little context, which makes the strange contrast between heavy steel and a tiny butterfly the entire attraction.', 'roadside', 'https://www.roadsideamerica.com/tip/25390', 'America/Chicago'),
  ('Tire Man', 'tire-man', 'roadside-oddities', 34.85153, -99.02222, 'Hobart', 'OK', 'A human figure assembled from stacked tires stands as an old-school roadside mascot. The rough homemade construction gives it more character than a polished modern statue.', 'roadside', 'https://www.travelok.com/Roadside_Oddities', 'America/Chicago'),
  ('Jeb the Mini-Golf Muffler Man', 'jeb-the-mini-golf-muffler-man', 'roadside-oddities', 34.16066, -94.7515, 'Broken Bow', 'OK', 'A giant Muffler Man named Jeb watches over an Old West-themed miniature-golf course north of Broken Bow. He is part roadside giant, part attraction prop and part deliberately fabricated frontier character.', 'limited', 'https://www.travelok.com/listings/view.profile/id.25359', 'America/Chicago'),
  ('Comecos Cemetery', 'comecos-cemetery', 'weird-history', 34.96524, -99.38841, 'Gotebo', 'OK', 'This tiny rural cemetery is known for unusually elaborate handmade grave decorations and concrete folk art. Visit only during lawful cemetery access and treat the site as an active burial ground rather than a novelty attraction.', 'limited', 'https://www.travelok.com/listings/view.profile/id.30588', 'America/Chicago'),
  ('Leedey Tornado Monument', 'leedey-tornado-monument', 'weird-history', 35.87001, -99.34822, 'Leedey', 'OK', 'Local children created this tornado-shaped metal memorial in 1997 to mark fifty years since the deadly 1947 Leedey tornado. Embedded objects such as a tricycle, boot and cow skull turn the disaster memorial into unusually personal public art.', 'open', 'https://web2.travelok.com/listings/view.profile/id.22828', 'America/Chicago'),
  ('One Room Jail', 'one-room-jail', 'roadside-oddities', 35.2204, -99.98889, 'Texola', 'OK', 'A tiny concrete jail survives in nearly vanished Texola near the Texas line. The single-room lockup and sparse surroundings give the stop the feel of a forgotten fragment of an older Route 66 town.', 'roadside', 'https://www.travelok.com/listings/view.profile/id.28033', 'America/Chicago'),
  ('Smallest National Park Landmark', 'smallest-national-park-landmark', 'weird-history', 35.87868, -97.42629, 'Guthrie', 'OK', 'A 1907 clerical mistake reportedly reduced a planned 100-foot-square commemorative plot to just 100 square feet. The tiny fenced landmark behind the post office is locally promoted as the country''s smallest national park, although it is not an official National Park Service unit.', 'open', 'https://www.travelok.com/listings/view.profile/id.25759', 'America/Chicago'),
  ('El Reno Mother Road Monument', 'el-reno-mother-road-monument', 'roadside-oddities', 35.53325, -97.95563, 'El Reno', 'OK', 'A modern Route 66 monument at Wade Street and Choctaw Avenue marks El Reno''s connection to the Mother Road. It adds a clear routable photo stop to a town already rich in highway and railroad history.', 'open', 'https://www.travelok.com/Roadside_Oddities', 'America/Chicago'),
  ('Oklahoma Spook Light — Devil''s Promenade Road', 'oklahoma-spook-light-devils-promenade-road', 'haunted', 36.94399, -94.61803, 'Quapaw', 'OK', 'For generations, people have reported a mysterious moving light along rural roads near the Oklahoma-Missouri border. Explanations range from distant vehicle headlights to folklore, so OddWay should present the phenomenon as an enduring local legend rather than a proven supernatural event.', 'roadside', 'https://www.travelok.com/listings/view.profile/id.21024', 'America/Chicago'),
  ('Healing Rock', 'healing-rock', 'folklore', 36.36309, -96.1137, 'Skiatook', 'OK', 'Local tradition has long attributed healing powers to a sandstone outcrop near Skiatook Lake. The story is the attraction; visitors should stay on permitted paths and avoid damaging or removing anything from the site.', 'limited', 'https://www.travelok.com/Roadside_Oddities', 'America/Chicago'),
  ('World''s Tallest Gas Pump — Heart of Route 66 Auto Museum', 'worlds-tallest-gas-pump-heart-of-route-66-auto-museum', 'roadside-oddities', 35.9958, -96.12937, 'Sapulpa', 'OK', 'A 66-foot replica gasoline pump stands outside the Heart of Route 66 Auto Museum and doubles as an observation structure. Its deliberately excessive height turns the most ordinary Route 66 object into a landmark.', 'open', 'https://www.heartofroute66.org/', 'America/Chicago'),
  ('24 Hour Prayer Teepee', '24-hour-prayer-teepee', 'roadside-oddities', 34.8939, -98.3657, 'Apache', 'OK', 'A brick teepee on church grounds is kept open around the clock as a place for prayer and reflection. The permanent masonry form is an unusual reinterpretation of a Plains symbol within a Christian devotional setting.', 'open', 'https://www.travelok.com/listings/view.profile/id.22676', 'America/Chicago'),
  ('Grave of Mister Ed', 'grave-of-mister-ed', 'roadside-oddities', 35.98884, -94.97028, 'Tahlequah', 'OK', 'A grave marker on private land is associated with Bamboo Harvester, the horse best known for portraying Mister Ed on television. This should be treated as a permission-only pilgrimage point, not an invitation to enter the property unannounced.', 'private', 'https://www.atlasobscura.com/places/grave-of-mister-ed', 'America/Chicago'),
  ('Elmer McCurdy Grave', 'elmer-mccurdy-grave', 'weird-history', 35.89814, -97.40353, 'Guthrie', 'OK', 'Outlaw Elmer McCurdy died in 1911, but his embalmed body spent decades being displayed by carnivals and sideshows before anyone realized it was a real corpse. He was finally buried in Summit View Cemetery in 1977 beneath concrete intended to prevent another removal.', 'limited', 'https://www.travelok.com/listings/view.profile/id.22040', 'America/Chicago'),
  ('Showmen''s Rest', 'showmens-rest', 'weird-history', 33.99864, -95.50376, 'Hugo', 'OK', 'A section of Mount Olivet Cemetery holds circus performers and workers beneath headstones decorated with elephants, tents and show-business imagery. The unusual memorials reflect Hugo''s long association with traveling circuses; visit respectfully.', 'limited', 'https://www.travelok.com/listings/view.profile/id.19347', 'America/Chicago'),
  ('Geronimo Grave', 'geronimo-grave', 'weird-history', 34.69646, -98.37076, 'Fort Sill', 'OK', 'Apache leader Geronimo is buried in the Fort Sill Apache cemetery beneath a distinctive stone monument. The grave is on an active U.S. Army installation, so identification, gate procedures and current access rules must be checked before routing there.', 'limited', 'https://www.army.mil/article/244620/fort_sill_cemeteries_are_final_resting_places_for_historical_figures', 'America/Chicago'),
  ('Chiefs Knoll at Fort Sill', 'chiefs-knoll-at-fort-sill', 'weird-history', 34.66952, -98.39542, 'Fort Sill', 'OK', 'Chiefs Knoll contains the graves of prominent Indigenous leaders and other historical figures connected with the Southern Plains and Fort Sill. Because it lies on an active military post and is a burial place, access should be conservative and respectful.', 'limited', 'https://www.army.mil/article/244620/fort_sill_cemeteries_are_final_resting_places_for_historical_figures', 'America/Chicago'),
  ('Pretty Boy Floyd Grave', 'pretty-boy-floyd-grave', 'weird-history', 35.50373, -94.6803, 'Akins', 'OK', 'Bank robber Charles Arthur Pretty Boy Floyd is buried in Akins Cemetery near his childhood home region. His grave remains a concrete pilgrimage point tied to one of Oklahoma''s most mythologized Depression-era outlaws.', 'limited', 'https://www.travelok.com/articles/oklahomas-legendary-outlaws', 'America/Chicago'),
  ('Cain''s Ballroom', 'cains-ballroom', 'weird-history', 36.16068, -95.99314, 'Tulsa', 'OK', 'The former garage became one of the most important venues in western swing through Bob Wills and the Texas Playboys. The preserved dance hall still operates, carrying a century of Tulsa music history into an active venue.', 'limited', 'https://www.cainsballroom.com/', 'America/Chicago'),
  ('Tulsa Theater', 'tulsa-theater', 'haunted', 36.15811, -95.99539, 'Tulsa', 'OK', 'Opened in 1914 as Convention Hall, this ornate downtown theater has accumulated stories of unexplained sounds and apparitions alongside its music history. It remains an active venue, so paranormal claims should be treated as local lore and access follows event schedules.', 'limited', 'https://www.travelok.com/articles/top-haunted-places-in-oklahoma', 'America/Chicago'),
  ('Poncan Theatre', 'poncan-theatre', 'haunted', 36.70379, -97.08349, 'Ponca City', 'OK', 'This restored 1920s atmospheric theater is known both for its elaborate interior and for local ghost stories connected with the building. Tours and performances provide lawful access to a site that otherwise often appears in haunted-Oklahoma lists.', 'limited', 'https://www.poncantheatre.org/', 'America/Chicago'),
  ('Constantine Theater', 'constantine-theater', 'haunted', 36.66317, -96.34076, 'Pawhuska', 'OK', 'The historic Constantine Theater preserves an ornate performance space in downtown Pawhuska and has developed a reputation for reported unexplained activity. It remains a functioning theater, so visit through scheduled events or authorized access.', 'limited', 'https://www.travelok.com/articles/top-haunted-places-in-oklahoma', 'America/Chicago'),
  ('Historic Fort Reno', 'historic-fort-reno', 'weird-history', 35.53694, -98.03408, 'El Reno', 'OK', 'Fort Reno began as a frontier military post in 1874 and later held German and Italian prisoners of war during World War II. Historic buildings, a cemetery and military artifacts give the site several layers of unusually concentrated history.', 'limited', 'https://fortreno.org/', 'America/Chicago'),
  ('Fort Washita Historic Site', 'fort-washita-historic-site', 'weird-history', 34.10223, -96.54689, 'Durant', 'OK', 'Established in 1842, Fort Washita served the frontier and later Confederate forces during the Civil War. Stone ruins and reconstructed buildings make the military landscape physically legible rather than just a marker in a field.', 'limited', 'https://www.chickasaw.net/our-nation/locations/fort-washita.aspx', 'America/Chicago'),
  ('Ritz Theater', 'ritz-theater', 'haunted', 35.32756, -96.92406, 'Shawnee', 'OK', 'The restored downtown theater is associated with local stories of unusual sounds and apparitions. It also survives as a tangible piece of early movie-house architecture, making it useful even for travelers who are skeptical of the ghost lore.', 'limited', 'https://www.travelok.com/articles/top-haunted-places-in-oklahoma', 'America/Chicago'),
  ('The Skirvin Hilton', 'the-skirvin-hilton', 'haunted', 35.46894, -97.51389, 'Oklahoma City', 'OK', 'Oklahoma City''s historic Skirvin hotel is tied to one of the state''s best-known hotel ghost legends, usually centered on a woman called Effie. The hotel is an active business, and the story should be presented as folklore rather than verified paranormal activity.', 'limited', 'https://www.travelok.com/articles/top-haunted-places-in-oklahoma', 'America/Chicago'),
  ('Beaver Dunes Park', 'beaver-dunes-park', 'haunted', 36.84018, -100.51382, 'Beaver', 'OK', 'The sand dunes north of Beaver are sometimes promoted in regional lore as the site of unexplained disappearances and strange phenomena, including fanciful Bermuda Triangle comparisons. The real visitable landscape is a public dune park; the supernatural layer remains folklore.', 'open', 'https://www.travelok.com/listings/view.profile/id.406', 'America/Chicago'),
  ('Ingalls Ghost Town', 'ingalls-ghost-town', 'weird-history', 36.1018, -96.88135, 'Ingalls', 'OK', 'Once a hideout area for the Doolin-Dalton gang, Ingalls was the scene of a deadly 1893 shootout between lawmen and outlaws. Only fragments of the settlement remain, making it a true place-based outlaw and ghost-town stop rather than a recreated western village.', 'roadside', 'https://www.travelok.com/articles/oklahomaghosttowns', 'America/Chicago'),
  ('Adamson Ghost Town', 'adamson-ghost-town', 'weird-history', 34.9241, -95.5471, 'Adamson', 'OK', 'Adamson grew around coal mining before accidents, mine closures and declining production emptied the community. Remnants of the settlement remain in the wooded hills of southeastern Oklahoma; stay on public roads and do not enter unstable mine workings or private structures.', 'roadside', 'https://www.travelok.com/articles/oklahomaghosttowns', 'America/Chicago'),
  ('Boggy Depot State Park', 'boggy-depot-state-park', 'weird-history', 34.3196, -96.30718, 'Atoka', 'OK', 'Boggy Depot was once an important Choctaw Nation town, stage stop and Civil War supply point before railroads bypassed it. The modern park preserves a cemetery, archaeological traces and interpretation from a community that largely disappeared.', 'open', 'https://www.travelok.com/listings/view.profile/id.820', 'America/Chicago'),
  ('Doaksville Archaeological Site', 'doaksville-archaeological-site', 'weird-history', 34.03487, -95.26987, 'Fort Towson', 'OK', 'Doaksville was a major nineteenth-century Choctaw Nation town and the location where Confederate Brigadier General Stand Watie surrendered in 1865. Archaeological remains lie near Fort Towson and should be visited without disturbing the protected site.', 'limited', 'https://www.okhistory.org/about/markers.php?action=Search&county=Choctaw', 'America/Chicago'),
  ('Picher Ghost Town', 'picher-ghost-town', 'weird-history', 36.98438, -94.83108, 'Picher', 'OK', 'The former lead-and-zinc boomtown was largely abandoned after severe mining contamination, subsidence and a devastating 2008 tornado. It is historically compelling but environmentally hazardous; view from lawful public roads and never climb chat piles or enter abandoned structures.', 'roadside', 'https://www.travelok.com/articles/oklahomaghosttowns', 'America/Chicago'),
  ('Robbers Cave State Park', 'robbers-cave-state-park', 'folklore', 34.99501, -95.32688, 'Wilburton', 'OK', 'Caves and rugged sandstone terrain in the Sans Bois Mountains are traditionally associated with outlaws including Jesse James and Belle Starr. The park gives that legend a safe, public landscape rather than directing travelers toward vague private hideout claims.', 'open', 'https://www.travelok.com/state-parks/robbers-cave-state-park', 'America/Chicago'),
  ('Heavener Runestone Park', 'heavener-runestone-park', 'folklore', 34.9001, -94.578, 'Heavener', 'OK', 'A large rock bears carved characters once promoted as evidence of pre-Columbian Viking exploration in Oklahoma. Mainstream archaeology does not accept that claim, but the inscription and the history of competing interpretations make the park a strong pseudoarchaeology-and-folklore stop.', 'open', 'https://www.heavenerrunestonepark.com/', 'America/Chicago'),
  ('Alabaster Caverns State Park', 'alabaster-caverns-state-park', 'roadside-oddities', 36.69824, -99.13333, 'Freedom', 'OK', 'One of the world''s largest natural gypsum caves open to public touring runs beneath the plains of northwestern Oklahoma. Guided cave access and the unusual alabaster formations make it one of the state''s strongest underground OddWay sites.', 'limited', 'https://www.travelok.com/state-parks/alabaster-caverns-state-park', 'America/Chicago'),
  ('Salt Plains State Park — Selenite Crystal Digging Area', 'salt-plains-state-park-selenite-crystal-digging-area', 'roadside-oddities', 36.74314, -98.13228, 'Jet', 'OK', 'The salt flats are famous for hourglass-shaped selenite crystals that form with trapped sand and can be dug during the legal collecting season. The stark white landscape looks more like a dried inland sea than typical Oklahoma prairie.', 'limited', 'https://www.fws.gov/refuge/salt-plains/visit-us/activities/crystal-digging', 'America/Chicago'),
  ('Gloss Mountain State Park', 'gloss-mountain-state-park', 'roadside-oddities', 36.36301, -98.57908, 'Fairview', 'OK', 'Selenite crystals in the mesa cap rock glint in the sun, producing the Glass versus Gloss Mountains naming story that has followed the range for generations. A steep stair-and-trail climb reaches the top of Cathedral Mountain.', 'open', 'https://www.travelok.com/state-parks/gloss-mountain-state-park', 'America/Chicago'),
  ('Little Sahara State Park', 'little-sahara-state-park', 'roadside-oddities', 36.53352, -98.88139, 'Waynoka', 'OK', 'More than a thousand acres of shifting sand dunes create an unexpectedly desert-like landscape in northwestern Oklahoma. The park is heavily used by off-road vehicles, so pedestrians should follow current safety and access rules.', 'open', 'https://www.travelok.com/state-parks/little-sahara-state-park', 'America/Chicago'),
  ('Black Mesa State Park', 'black-mesa-state-park', 'roadside-oddities', 36.84059, -102.88152, 'Kenton', 'OK', 'Dark volcanic rock, high-plains grassland and exceptionally dark skies make this remote Panhandle park feel unlike most of Oklahoma. It is also the practical base area for exploring the state''s far western mesa country.', 'open', 'https://www.travelok.com/state-parks/black-mesa-state-park', 'America/Chicago'),
  ('Black Mesa Summit Trailhead', 'black-mesa-summit-trailhead', 'roadside-oddities', 36.96055, -102.96362, 'Kenton', 'OK', 'An 8.4-mile round-trip trail climbs from this public trailhead to Oklahoma''s highest point near the New Mexico border. The summit itself is remote, so the trailhead is the safer routable pin; carry water and check weather before attempting the hike.', 'limited', 'https://www.travelok.com/listings/view.profile/id.672', 'America/Chicago'),
  ('Holy City of the Wichitas', 'holy-city-of-the-wichitas', 'roadside-oddities', 34.74257, -98.59034, 'Lawton', 'OK', 'Stone buildings and walls create a miniature biblical landscape in the Wichita Mountains, built as the setting for a long-running Easter passion play. Even outside performances, the fortress-like complex is one of Oklahoma''s strangest constructed environments.', 'limited', 'https://theholycitylawton.com/', 'America/Chicago'),
  ('Parallel Forest', 'parallel-forest', 'roadside-oddities', 34.7507, -98.58034, 'Lawton', 'OK', 'Thousands of red cedars were planted in eerily straight rows about six feet apart as part of erosion-control work. The perfect spacing gives an ordinary forest an unnatural visual rhythm that has also inspired local ghost stories.', 'open', 'https://www.fws.gov/refuge/wichita-mountains', 'America/Chicago'),
  ('Collings Castle', 'collings-castle', 'weird-history', 34.42707, -97.14729, 'Davis', 'OK', 'A hand-built stone castle from the Great Depression era clings to a steep hillside inside Turner Falls Park. Narrow openings, rough masonry and partial deterioration make it look far older than its twentieth-century construction date.', 'limited', 'https://www.turnerfallspark.com/', 'America/Chicago'),
  ('Cavanal Hill — World''s Highest Hill Claim', 'cavanal-hill-worlds-highest-hill-claim', 'roadside-oddities', 35.07093, -94.67939, 'Poteau', 'OK', 'Cavanal Hill is locally promoted as the world''s highest hill because its rise is often cited at just under the traditional 2,000-foot threshold for a mountain. The classification is promotional rather than a universal geographic rule, but the claim has become part of the place''s identity.', 'open', 'https://www.travelok.com/listings/view.profile/id.1209', 'America/Chicago'),
  ('Redbud Park Outlaw Cave', 'redbud-park-outlaw-cave', 'folklore', 34.64778, -97.95099, 'Marlow', 'OK', 'A small cave in Redbud Park is tied by local tradition to Marlow-area outlaw stories and the Marlow brothers. The public park gives travelers a concrete, accessible anchor for legends that otherwise blur into regional folklore.', 'open', 'https://www.travelok.com/listings/view.profile/id.22827', 'America/Chicago'),
  ('Museum of Osteology', 'museum-of-osteology', 'museums', 35.36483, -97.44184, 'Oklahoma City', 'OK', 'Hundreds of real animal skeletons fill a museum devoted almost entirely to comparative anatomy. The dense displays of skulls, articulated skeletons and unusual species make it one of Oklahoma''s clearest cabinet-of-curiosities style museums.', 'open', 'https://www.skeletonmuseum.com/', 'America/Chicago'),
  ('Mabee-Gerrer Museum of Art — Egyptian Collection', 'mabee-gerrer-museum-of-art-egyptian-collection', 'museums', 35.36607, -96.95508, 'Shawnee', 'OK', 'This university museum contains an unexpectedly strong collection of Egyptian antiquities, including a mummy, alongside art and archaeological material from around the world. The Egyptian galleries give it a much stranger profile than a typical regional art museum.', 'open', 'https://www.mgmoa.org/', 'America/Chicago'),
  ('American Pigeon Museum & Library', 'american-pigeon-museum-library', 'museums', 35.53632, -97.47135, 'Oklahoma City', 'OK', 'A museum devoted to pigeons documents racing, military messenger birds, fancy breeds and the long relationship between humans and domesticated pigeons. It is one of the state''s most narrowly focused specialty museums.', 'limited', 'https://www.theamericanpigeonmuseum.org/', 'America/Chicago'),
  ('American Banjo Museum', 'american-banjo-museum', 'museums', 35.46677, -97.51154, 'Oklahoma City', 'OK', 'Hundreds of ornate banjos trace the instrument from minstrel-era history through jazz, bluegrass and modern performance. Elaborately decorated instruments and a highly specific collecting focus make the museum an unusually strong niche stop.', 'open', 'https://americanbanjomuseum.com/', 'America/Chicago'),
  ('Oklahoma Frontier Drugstore Museum', 'oklahoma-frontier-drugstore-museum', 'weird-history', 35.87819, -97.42724, 'Guthrie', 'OK', 'Historic pharmacy fixtures, medicine bottles, patent remedies and equipment fill a recreated frontier drugstore environment. The displays preserve the sometimes-unsettling overlap between medicine, advertising and commerce in early Oklahoma.', 'limited', 'https://www.okpharmheritage.com/', 'America/Chicago'),
  ('Oklahoma Museum of Telephone History', 'oklahoma-museum-of-telephone-history', 'museums', 35.47104, -97.51523, 'Oklahoma City', 'OK', 'Switchboards, telephones, signs and telecommunications equipment document the rapidly changing technology behind everyday conversation. The specialized collection turns obsolete infrastructure into a surprisingly visual museum.', 'limited', 'https://www.travelok.com/Roadside_Oddities', 'America/Chicago'),
  ('Twister Museum', 'twister-museum', 'weird-history', 36.88041, -97.92468, 'Wakita', 'OK', 'Wakita served as a major filming location for the 1996 movie Twister, and this small museum preserves props, photographs and production memorabilia. The town itself still carries visual traces of its role in the tornado film.', 'limited', 'https://twistercountry.com/', 'America/Chicago'),
  ('Toy & Action Figure Museum', 'toy-action-figure-museum', 'museums', 34.74012, -97.21957, 'Pauls Valley', 'OK', 'Thousands of action figures, toys and comic-related objects fill a museum built around the visual history of modern character merchandising. Displays range from superhero collections to an enormous staged action-figure diorama.', 'open', 'https://www.toyandactionfiguremuseum.com/', 'America/Chicago'),
  ('J.M. Davis Arms & Historical Museum', 'jm-davis-arms-historical-museum', 'museums', 36.3146, -95.61503, 'Claremore', 'OK', 'The museum holds one of the world''s largest privately assembled firearms collections alongside swords, outlaw artifacts, musical instruments and assorted curiosities. Its sheer density and eccentric breadth make it more cabinet collection than conventional weapons museum.', 'open', 'https://www.thegunmuseum.com/', 'America/Chicago'),
  ('Tom Mix Museum', 'tom-mix-museum', 'roadside-oddities', 36.79832, -95.93823, 'Dewey', 'OK', 'This museum is devoted to silent-film cowboy star Tom Mix, who worked in the Dewey area before becoming an early Hollywood western icon. Costumes, saddles, photographs and memorabilia preserve the strange bridge between real ranch culture and manufactured screen mythology.', 'limited', 'https://www.okhistory.org/sites/tommix', 'America/Chicago'),
  ('Stafford Air & Space Museum', 'stafford-air-space-museum', 'weird-history', 35.53889, -98.66778, 'Weatherford', 'OK', 'Named for astronaut Thomas P. Stafford, this museum holds aircraft, rocket engines, spacecraft-related hardware and thousands of aviation artifacts. Full-scale machines and spaceflight objects make it substantially more tactile than a general science museum.', 'open', 'https://www.staffordmuseum.org/', 'America/Chicago'),
  ('Seaba Station Motorcycle Museum', 'seaba-station-motorcycle-museum', 'roadside-oddities', 35.68652, -97.00026, 'Warwick', 'OK', 'A restored 1920s Route 66 service station now contains dozens of motorcycles ranging from early machines to unusual custom bikes. The reuse of the roadside station makes the building and collection equally important to the stop.', 'limited', 'https://seabastation.com/', 'America/Chicago'),
  ('Oklahoma Route 66 Museum', 'oklahoma-route-66-museum', 'roadside-oddities', 35.50657, -98.9869, 'Clinton', 'OK', 'Immersive galleries move through different eras of Route 66 using vehicles, signs, music and recreated roadside environments. The museum is one of the strongest places in the state for understanding the highway beyond individual roadside photo stops.', 'open', 'https://www.okhistory.org/sites/visit-route-66', 'America/Chicago'),
  ('National Route 66 & Transportation Museum', 'national-route-66-transportation-museum', 'roadside-oddities', 35.4122, -99.43585, 'Elk City', 'OK', 'This large museum complex interprets all eight Route 66 states through recreated scenes, vehicles and transportation exhibits. A giant roadside figure at the entrance and an old-town complex extend the experience outside the main galleries.', 'open', 'https://www.travelok.com/listings/view.profile/id.5284', 'America/Chicago'),
  ('Chandler Route 66 Interpretive Center', 'chandler-route-66-interpretive-center', 'roadside-oddities', 35.70959, -96.87702, 'Chandler', 'OK', 'Housed in a former National Guard armory, the center uses video installations, unusual seating and oral-history material to interpret Route 66. Its presentation is more experiential than a conventional display-case museum.', 'open', 'https://www.route66interpretivecenter.org/', 'America/Chicago'),
  ('No Man''s Land Museum', 'no-mans-land-museum', 'museums', 36.59471, -101.6352, 'Goodwell', 'OK', 'The museum focuses on the Oklahoma Panhandle, once widely called No Man''s Land, with archaeology, fossils, agricultural material and regional artifacts. Its location near the center of the Panhandle gives context to one of the state''s strangest geographic histories.', 'limited', 'https://www.opsu.edu/no-mans-land-museum/', 'America/Chicago'),
  ('Eskridge Hotel Museum', 'eskridge-hotel-museum', 'weird-history', 34.64294, -97.16967, 'Wynnewood', 'OK', 'This restored historic hotel preserves period rooms, local artifacts and the atmosphere of a small-town lodging house from another era. The building''s layered commercial and community history makes it more immersive than a standard local-history room.', 'limited', 'https://www.travelok.com/listings/search/3?city=Wynnewood', 'America/Chicago'),
  ('Spiro Mounds Archaeological Center', 'spiro-mounds-archaeological-center', 'weird-history', 35.31173, -94.56843, 'Spiro', 'OK', 'One of the most important Mississippian ceremonial centers west of the Mississippi River survives here as protected earthworks and archaeological landscape. The museum and trails interpret a complex Indigenous community; mounds and cultural resources must not be climbed, collected from or disturbed.', 'limited', 'https://www.okhistory.org/sites/visit-spiro-mounds', 'America/Chicago'),
  ('Washita Battlefield National Historic Site', 'washita-battlefield-national-historic-site', 'weird-history', 35.61672, -99.6863, 'Cheyenne', 'OK', 'The National Park Service interprets the 1868 attack by Lt. Col. George A. Custer''s forces on a Southern Cheyenne village led by Peace Chief Black Kettle. Begin at the visitor center and follow designated trails to approach the landscape with appropriate historical and cultural context.', 'open', 'https://www.nps.gov/waba/', 'America/Chicago'),
  ('Honey Springs Battlefield', 'honey-springs-battlefield', 'weird-history', 35.52356, -95.48512, 'Checotah', 'OK', 'The 1863 Battle of Honey Springs was the largest Civil War engagement in Indian Territory and involved Native, Black and white soldiers. A modern visitor center and preserved battlefield landscape interpret a conflict often omitted from standard Civil War tourism.', 'limited', 'https://www.okhistory.org/sites/visit-honey-springs', 'America/Chicago'),
  ('Fort Gibson Historic Site', 'fort-gibson-historic-site', 'weird-history', 35.80399, -95.25699, 'Fort Gibson', 'OK', 'Established in 1824, Fort Gibson became a major U.S. military post on the western frontier and later figured in Indian Removal and Civil War history. Reconstructed and original-era structures make the complex a tangible counterpart to nearby archaeological and tribal-history sites.', 'limited', 'https://www.okhistory.org/sites/fortgibson', 'America/Chicago'),
  ('Fort Towson Historic Site', 'fort-towson-historic-site', 'weird-history', 34.02788, -95.25634, 'Fort Towson', 'OK', 'Founded in 1824 near the Red River borderlands, Fort Towson served the U.S. Army, the Choctaw Nation region and later Confederate forces. The site also connects directly with nearby Doaksville, where Stand Watie surrendered in 1865.', 'limited', 'https://www.okhistory.org/sites/forttowson', 'America/Chicago'),
  ('Sod House Museum', 'sod-house-museum', 'roadside-oddities', 36.47216, -98.42572, 'Aline', 'OK', 'A genuine 1894 sod house remains preserved beneath a protective structure on its original farmstead. Visitors can step inside a surviving example of the earth-built homes used by settlers where lumber was scarce.', 'limited', 'https://www.okhistory.org/sites/visit-sod-house', 'America/Chicago'),
  ('Pioneer Woman Museum & Statue', 'pioneer-woman-museum-statue', 'roadside-oddities', 36.71049, -97.06558, 'Ponca City', 'OK', 'A large bronze Pioneer Woman leads a child beside a museum devoted to the experiences and mythology of women in Oklahoma settlement history. The monumental statue and highly focused museum make the complex more distinctive than a general pioneer museum.', 'limited', 'https://www.okhistory.org/sites/pioneerwoman', 'America/Chicago'),
  ('Standing Bear Park, Museum & Monument', 'standing-bear-park-museum-monument', 'weird-history', 36.68285, -97.07595, 'Ponca City', 'OK', 'This public park and museum honor Ponca Chief Standing Bear, whose 1879 federal court case affirmed that Native Americans were persons entitled to seek habeas corpus protection. A large statue and interpretive spaces make the site both a legal-history landmark and a major Indigenous cultural stop.', 'open', 'https://www.standingbearpark.com/', 'America/Chicago')
on conflict (slug) do update set
  name          = excluded.name,
  category      = excluded.category,
  city          = excluded.city,
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  timezone      = excluded.timezone;
